import React from "react";

const TotalExpense = ({ expenses }) => {
  const total = expenses.reduce(
    (sum, expense) => sum + Number(expense.amount),
    0
  );

  return (
    <div className="total-expense">
      <h2>Total Expense: ₹{total}</h2>
    </div>
  );
};

export default TotalExpense;
